#!/usr/bin/env python3
import json
from collections import Counter

programs_dir = '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out/play/users/u043/system/state/workspace/programs'
with open(f'{programs_dir}/task-122dfdfb.json', 'r') as f:
    demos = json.load(f)

m = [[2,2,2,3], [2,2,0,2], [1,3,3,0], [2,3,3,3]]
regions = [(0,3), (5,9), (10,14), (15,19)]

def compute(inp):
    out = [[0]*4 for _ in range(4)]
    for i in range(4):
        for j in range(4):
            reg = m[i][j]
            rstart, rend = regions[reg]
            vals = [inp[i][c] for c in range(rstart, rend)]
            nonz = [v for v in vals if v != 0]
            if nonz:
                out[i][j] = Counter(nonz).most_common(1)[0][0]
            else:
                # Forward borrow: borrow from same region in row i+1, i+2, etc
                for r in range(i + 1, 4):
                    bvals = [inp[r][c] for c in range(rstart, rend)]
                    bnonz = [v for v in bvals if v != 0]
                    if bnonz:
                        out[i][j] = Counter(bnonz).most_common(1)[0][0]
                        break
                else:
                    # No forward borrow, try backward
                    for r in range(i - 1, -1, -1):
                        bvals = [inp[r][c] for c in range(rstart, rend)]
                        bnonz = [v for v in bvals if v != 0]
                        if bnonz:
                            out[i][j] = Counter(bnonz).most_common(1)[0][0]
                            break
                    else:
                        out[i][j] = 0
    return out

print("Verifying all 4 demos:")
for idx, (inp, expected) in enumerate(zip(demos['inputs'], demos['outputs'])):
    result = compute(inp)
    match = (result == expected)
    print(f"Demo {idx}: {'✓' if match else '✗'}")
    if not match:
        print(f"  Expected: {expected}")
        print(f"  Got:      {result}")
    else:
        print(f"  Output matches expected!")

